<?php $__env->startPush('scripts'); ?><script>
let t=localStorage.getItem('fh_branch_token')||'';const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const money=x=>'₱'+Number(x||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});async function api(u,o={}){o.headers={...(o.headers||{}),Accept:'application/json','Content-Type':'application/json',Authorization:'Bearer '+t};const r=await fetch(u,o),d=await r.json();if(!r.ok)throw Error(d.message||'Request failed');return d;}async function load(){try{if(!t){const r=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({email:email.value,password:password.value})});const d=await r.json();if(!r.ok)throw Error(d.message||'Login failed');t=d.token;localStorage.setItem('fh_branch_token',t);}const s=await api('/api/v1/reports/summary');cards.innerHTML=Object.entries({Orders:s.orders,'Paid orders':s.paid_orders,'Sales':money(s.sales),'Average order':money(s.average_order_value),'Cancelled':s.cancelled}).map(([k,v])=>`<div class="col-6 col-lg"><div class="card stat p-3"><small class="text-secondary">${k}</small><div class="fs-3 fw-bold">${v}</div></div></div>`).join('');const rows=await api('/api/v1/reports/sales');sales.querySelector('tbody').innerHTML=rows.map(x=>`<tr><td>${esc(x.day)}</td><td>${esc(x.orders)}</td><td>${money(x.sales)}</td></tr>`).join('')||'<tr><td colspan="3">No sales data.</td></tr>';const top=await api('/api/v1/reports/top-products');products.innerHTML=top.map((x,i)=>`<div class="d-flex justify-content-between border-bottom py-2"><span><strong>${i+1}. ${esc(x.product_name)}</strong><small class="d-block text-secondary">${esc(x.quantity)} sold</small></span><span>${money(x.sales)}</span></div>`).join('')||'<div class="text-secondary">No product sales.</div>';login.classList.add('d-none');app.classList.remove('d-none');}catch(e){msg.textContent=e.message;msg.className='small mt-2 text-danger';}}f.addEventListener('submit',e=>{e.preventDefault();load();});if(t)load();</script><?php $__env->stopPush(); ?>

